// Создание regex: /шаблон/флаги
const digit = /\d/;  // любая цифра

// .test() — проверяет, есть ли совпадение (true/false)
console.log(digit.test("a"));  // false — нет цифры
console.log(digit.test("3"));  // true — есть цифра

// .match() — возвращает найденные совпадения
console.log("abc123".match(/\d/));  // ["1"] — первое совпадение
console.log("abc123".match(/\d/g)); // ["1","2","3"] — все (флаг g)

// Литерал — когда шаблон известен заранее
const email = /[a-z]+@[a-z]+\.[a-z]+/;

// new RegExp — когда шаблон строится динамически
const word = "hello";
const re = new RegExp(word);  // /hello/
console.log(re.test("say hello"));  // true

// new RegExp с экранированием: двойной \
const path = new RegExp("C:\\\\Users");  // ищет C:\Users

// \d — цифра (0-9)
console.log(/\d/.test("5"));  // true

// \w — слово (a-z, A-Z, 0-9, _)
console.log(/\w/.test("A"));  // true
console.log(/\w/.test("_"));  // true

// \s — пробел (пробел, табуляция)
console.log(/\s/.test(" "));  // true

// . — любой символ
console.log(/./.test("x"));   // true
console.log(/./.test("1"));   // true
console.log(/./.test("\n"));  // false — точка не ловит перенос строки

// [abc] — один из: a, b или c
console.log(/[abc]/.test("b"));  // true
console.log(/[abc]/.test("d"));  // false

// Без ^ и $ — ищет в любом месте
console.log(/123/.test("abc123def"));  // true — нашло 123 внутри

// С ^ и $ — вся строка должна соответствовать
console.log(/^123$/.test("123"));      // true — вся строка '123'
console.log(/^123$/.test("1234"));     // false — есть лишняя цифра
console.log(/^123$/.test("0123"));     // false — есть лишняя цифра в начале

