// БАГ: точка ловит любой символ
console.log(/file.txt/.test("fileXtxt"));  // true — точка = X!
console.log(/file.txt/.test("file.txt"));  // true

// ПРАВИЛЬНО: экранированная точка
console.log(/file\.txt/.test("fileXtxt"));  // false — X не точка
console.log(/file\.txt/.test("file.txt"));  // true — настоящая точка

// Валидация email
function isValidEmail(str) {
  return /^[\w.]+@[\w]+\.[a-z]{2,}$/.test(str);
}

console.log(isValidEmail("alice@mail.com"));  // true
console.log(isValidEmail("bad@"));             // false
console.log(isValidEmail("noat.com"));         // false

// Валидация телефона
function isValidPhone(str) {
  return /^\d{3}-\d{3}-\d{4}$/.test(str);
}

console.log(isValidPhone("555-123-4567"));  // true
console.log(isValidPhone("5551234567"));    // false — нет дефисов

// Без флага g — одно совпадение
console.log("abc123def456".match(/\d+/));
// ["123", index: 3, input: "abc123def456"]

// С флагом g — все совпадения (только строки)
console.log("abc123def456".match(/\d+/g));
// ["123", "456"]

// Поиск слов из 3 букв
console.log("The quick brown fox".match(/[a-z]{3}/gi));
// ["The", "qui", "bro", "fox"]

// Заменяем первое совпадение
console.log("hello world".replace(/world/, "there"));
// "hello there"

// Заменяем ВСЕ (флаг g)
console.log("aaa bbb aaa".replace(/aaa/g, "ccc"));
// "ccc bbb ccc"

// Заменяем цифры на [NUM]
console.log("I have 3 cats".replace(/\d/g, "[NUM]"));
// "I have [NUM] cats"

// Захват групп: (день).(месяц).(год)
const date = "25.12.2026";
console.log(date.replace(/(\d{2})\.(\d{2})\.(\d{4})/, "$2/$1/$3"));
// "12/25/2026" — переформатировал дату

// match с группами — возвращает массив с группами
const match = "25.12.2026".match(/(\d{2})\.(\d{2})\.(\d{4})/);
console.log(match[0]);  // "25.12.2026" — полное совпадение
console.log(match[1]);  // "25" — первая группа
console.log(match[2]);  // "12" — вторая группа
console.log(match[3]);  // "2026" — третья группа

// g — global: все совпадения
console.log("Hello hello HELLO".match(/hello/g));  // null — регистр важен!
console.log("Hello hello HELLO".match(/hello/gi)); // ["Hello", "hello", "HELLO"]

// i — ignore case: без учёта регистра
console.log(/hello/.test("Hello"));        // false
console.log(/hello/i.test("Hello"));       // true

// m — multiline: ^ и $ построчно
const text = "first line\nsecond line\nthird line";
console.log(text.match(/^\w+/gm));  // ["first", "second", "third"]

// Цифры
console.log(/\d+/.test("123"));  // true

// Только буквы
console.log(/^[a-z]+$/.test("hello"));  // true
console.log(/^[a-z]+$/.test("hello1")); // false

// Email (простой)
console.log(/^[\w.-]+@[\w.-]+\.[a-z]+$/.test("user@mail.com"));  // true

// Телефон (формат XXX-XXX-XXXX)
console.log(/^\d{3}-\d{3}-\d{4}$/.test("555-123-4567"));  // true

// URL
console.log(/^https?:\/\//.test("https://example.com"));  // true

